def rarity_weights(luck, level=20, stage=1):
    """Unrestricted offer roll, dC in inspected client; weights are normalized."""
    a = max(0, luck) / 100
    score = level + max(0, luck) / 8 + (stage - 1) * 12
    ramp = lambda lo, hi: max(0, min(1, (score - lo) / (hi - lo)))
    weights = [70 / (1 + a), 24 * (1 + .5 * a), 5 * (1 + a)**2 * ramp(3, 10),
               .9 * (1 + a)**3 * ramp(8, 18), .12 * (1 + a)**4 * ramp(14, 26)]
    return [100 * x / sum(weights) for x in weights]


def apply_longtail(ctx):
    P, pages, article, table, ref = (ctx[x] for x in ['P', 'PAGES', 'article', 'table', 'ref'])
    old = ctx['DATE'], ctx['VERSION']
    ctx['DATE'], ctx['VERSION'] = CHECKED, 'v0.8.62'
    scope = '<p class="note">Original-game scope: pokebonk.com v0.8.62, checked October 28. Our Play window uses a separate third-party v0.8.27 edition and separate progress. Recommendations here are source-based decisions; no original-game full clear, catch, reward claim or co-op completion was tested.</p>'
    article('how-to-win', 'How to Win PokeBonk: Classic Route & Survival Goals', 'Finish a PokeBonk Classic run',
        'Follow the Classic route from guardian to reward and final exit, distinguish Survival milestones from wins, and diagnose what stopped your run.',
        f'To complete a Classic map, advance through its zones, defeat the final encounter and use the exit portal. Staying alive for ten minutes or beating an ordinary guardian is not the map win. Survival is an endurance mode with recurring milestones, so choose Classic if your goal is a finite clear.{ref(1)}', [
        ('goal', 'Set the right finishing condition', scope + table(['Goal', 'Choose / check', 'What does not establish it'], [('First finite clear', 'Classic; an unlocked map and difficulty you can select.', 'Surviving ten minutes without using the route objectives.'), ('New-region progress', 'Read the region gate and the accepted result after a Classic clear.', 'A similar-looking biome record in the data file.'), ('Survival record', 'Survival; track endurance and milestone bosses.', 'A milestone is not a Classic map victory.'), ('League partner unlock', 'Meet that partner’s challenge, then its capture path.', 'A map clear alone does not finish every League challenge.')]) + f'<p>Start with Classic, Viridian Forest and Normal when available if you want to learn one bounded route. This is editorial learning advice, not a measured easiest or fastest clear.{ref(2)}</p>'),
        ('route', 'Use an objective loop in each zone', f'<ol><li><strong>Prepare one coherent kit.</strong> Read the passive, keep useful early coverage and improve the attacks you actually have. A fusion is optional; do not sacrifice the run to a missing ingredient.</li><li><strong>Locate the guardian objective.</strong> Use the map and the nearby interaction prompt. The normal zone timer is not the command that summons every boss.</li><li><strong>Defeat the guardian.</strong> Keep space to respond to the visible attacks. If damage is insufficient, inspect move class/type and effective uptime before adding unrelated attacks.</li><li><strong>Collect the reward you intend to keep.</strong> The client marks a nearby Great Ball reward and warns before leaving it behind.</li><li><strong>Use the portal.</strong> Early exits advance the route. On a region with a sanctuary, the third zone leads into its final encounter; complete that encounter and enter the final exit to finish.</li><li><strong>Read the result.</strong> Confirm the accepted win and any unlock progress. A boss banner and a server-accepted map result are different checkpoints.</li></ol><p>The exit handler checks the stage and whether the map has a sanctuary. Follow the actual portal prompt rather than applying “three boss kills always ends everything” to every map.{ref(1)}</p>'),
        ('timer', 'Ten minutes makes waiting more dangerous', f'<p>In an ordinary Classic zone, stage time reaching 600 seconds starts the Final Swarm. The director scales swarm pressure afterward. This is neither an automatic win nor an instruction to wait ten minutes before activating the guardian.</p><p>If your plan is ready and the route objective is available, move toward it. If you are still collecting upgrades, decide whether the extra reward justifies the growing pressure. This is a risk decision, not a tested timing target.{ref(1)}</p>'),
        ('blocked', 'Identify the stage at which the clear failed', table(['What happened', 'Next comparison', 'Avoid this mistaken conclusion'], [('Died before the guardian', 'Look at the last damage source, recovery and movement; make one targeted change.', 'A late fusion on a guide is mandatory for the first zone.'), ('Guardian barely loses HP', 'Compare the selected move’s class/type and whether it can hit while you evade.', 'Every attack-speed, projectile or area offer improves every move equally.'), ('Guardian dead, no result screen', 'Find the reward/portal prompt and distinguish next-zone portal from final exit.', 'Boss defeat always ends the whole map.'), ('Timer passed 10:00', 'Check for Final Swarm and route availability.', 'A countdown must automatically award victory.'), ('Win shown but progression missing', 'Preserve the session; note map, mode, difficulty, version and result/error text.', 'Clearing browser data will repair an accepted-result problem.')]) + '<p>For a reliable comparison, keep partner, map, difficulty and permanent upgrades fixed, then record the point of failure. We have not collected a controlled series of clear attempts.</p>'),
        ('survival', 'Keep Survival milestones separate', f'<p>The checked definitions schedule a milestone every 300 seconds. A preceding live boss or other state can delay the actual spawn; “five-minute milestone” is a schedule, not a guarantee that a fight starts at that exact second. The ninth milestone is Mewtwo, nominally 45 minutes. Defeating it lets Survival continue and uses a different capture handoff from Classic.{ref(1)}{ref(2)}</p>')],
        SOURCES, [('maps/', 'Find regions, rewards and portals'), ('builds/', 'Choose a coherent starter route'), ('mewtwo/', 'Separate the two Mewtwo encounters')])
    article('how-to-catch-pokemon', 'How to Catch Pokemon in PokeBonk: League vs Support', 'Catch the right kind of PokeBonk partner',
        'Complete a League challenge, weaken the eligible encounter and use its capture prompt. Distinguish permanent unlocks, Alpha support and shiny rewards.',
        f'For a permanent playable League partner, first complete every condition on its challenge, then weaken its eligible encounter and use the nearby Poké Ball prompt. A captured Support Alpha or shiny is a different reward path; neither alone proves that the locked partner joined your League.{ref(1)}{ref(2)}', [
        ('target', 'Decide what you are trying to obtain', scope + table(['Capture context', 'What to verify', 'What it does not prove'], [('League encounter', 'The partner’s full challenge is done; its permanent League entry is added afterward.', 'One completed prerequisite is enough.'), ('Support Alpha / Friend Ball', 'The prompt says it fights alongside you this run.', 'You can choose it as a permanent starting partner next time.'), ('Shiny / Classic shiny', 'Read the collection, Look and support reward displayed for that capture.', 'A colour variant bypasses the corresponding League challenge.'), ('Mewtwo', 'Use its special Classic encounter after all gates, or distinguish the Survival boss.', 'It is selected from the normal roaming League pool.')]) + f'<p>The original runtime separates League, shiny and support handlers. Read the actual reward message before recording an unlock.{ref(1)}</p>'),
        ('steps', 'From a finished challenge to the throw', f'<ol><li><strong>Inspect League before the run.</strong> Confirm all conditions, including any one-run total, League-size or map gate. Pick a target whose challenge the game actually marks complete.</li><li><strong>Enter an eligible run.</strong> The ordinary League encounter handler picks from completed, not-yet-captured League challenges and excludes Mewtwo. You cannot select a specific target simply by marking a Build plan.</li><li><strong>Find and weaken the encounter.</strong> Follow its banner/marker. Continue until the game changes to the weakened state and offers a throw; ordinary KOs elsewhere are not captures.</li><li><strong>Approach immediately.</strong> In the ordinary solo capture path, the weakened window starts at ten seconds and the throw prompt requires proximity. Use the visible action button on touch, or the currently bound Interact action on desktop.</li><li><strong>React to the outcome.</strong> If it breaks free, the handler returns it to a fighting state; weaken it again if the encounter remains available. If it flees, there is no guaranteed immediate replacement in that run.</li><li><strong>Confirm the destination.</strong> Check the League entry and the same account/profile before expecting it on the next selection screen.</li></ol><p>The 50–120 second ordinary encounter schedule is not a guaranteed target arrival: eligibility, competing encounter state and later game changes still matter. Co-op mirror encounters and special boss takeovers have different windows; do not apply the ten-second solo rule to every capture.{ref(1)}</p>'),
        ('chance', 'When a throw fails', f'<p>The ordinary League throw uses a species capture-rate term, a bonus for previous failed throws, and a bonus when the target is paralyzed, asleep or frozen. It is not “every E press succeeds.” Special guaranteed handoffs use another branch.</p><p>Those three statuses are checked on the target. A high Status Chance stat or a Psychic-type move does not prove the required status is currently applied. We have not measured actual catch rates; this guide does not recommend importing main-series ball formulas.{ref(1)}</p>'),
        ('triage', 'Challenge full, but still not selectable?', table(['Observation', 'Check next'], [('Full challenge bar, no catch yet', 'Eligibility and permanent capture are separate; keep watching the actual eligible encounter.'), ('Caught an Alpha', 'Read whether it says support for this run; use the League card for permanent eligibility.'), ('Caught a shiny', 'Inspect collection/Look rewards and the separate League entry.'), ('Caught target, then changed website', 'Return to the exact host and account used for that result; third-party editions have independent progress.'), ('Correct host, entry still locked', 'Record target, challenge, encounter, result text and version for original-game support; preserve current session.')]) + '<p>Our unlock reference owns the 79 prerequisite rows; this page owns the encounter and capture decisions. No spawn deadline, account repair or capture success has been tested by this guide.</p>')],
        SOURCES, [('unlocks/', 'Read all League prerequisites'), ('mewtwo/', 'Use the special Mewtwo route'), ('wardrobe-mastery-looks/', 'Separate Looks from League progress')])
    article('mewtwo', 'PokeBonk Mewtwo: Unlock Gates, Classic & Survival', 'Find the correct Mewtwo encounter',
        'Check all Mewtwo unlock gates, understand the Classic encounter delays and separate the 45-minute Survival boss from a permanent League capture.',
        f'For the Classic League route, Mewtwo requires 60 League members, captures of Articuno, Zapdos and Moltres, and a Rocky Desert Hard clear. Then it uses a special boss encounter, not the ordinary roaming capture pool. The 45-minute Survival milestone is a separate encounter and does not perform Classic’s capture handoff.{ref(1)}{ref(2)}', [
        ('gates', 'Check every eligibility gate', scope + table(['Gate', 'Evidence to check on your profile', 'Common false positive'], [('60 League members', 'Permanent League membership count.', 'Counting every Pokédex form or this-run support.'), ('All three birds captured', 'Articuno, Zapdos and Moltres permanent capture progress.', 'Only defeating a similarly named boss.'), ('Rocky Desert Hard clear', 'Accepted desert result at Hard or a qualifying higher tier.', 'Forest Hard, Desert Normal or an unaccepted result.'), ('Mewtwo not already captured', 'It is an eligible, not-yet-owned League challenge.', 'Expecting the unlock encounter repeatedly after joining.')]) + f'<p>The League challenge defines all three gates together. Mew is different: its challenge is the other 78 League members. Do not apply Mew’s final-roster requirement to Mewtwo.{ref(2)}</p>'),
        ('classic', 'Why eligible Mewtwo may not appear immediately', f'<p>The checked Classic handler allows its ordinary special encounter in zone 2 or 3 after eligibility, with a scheduled 70–150 seconds of stage time. It also checks whether Mewtwo was already fought in that run.</p>' + table(['Potential blocker', 'What to do with that information'], [('Another boss alive, boss already summoned, or zone cleared', 'Do not expect a second scripted boss to start simultaneously.'), ('An event or Final Swarm active', 'This is not proof the League challenge failed; encounter state can block the start.'), ('Another capture roaming, weakened or being thrown', 'Finish the visible capture decision before assuming Mewtwo is missing.'), ('Wrong mode, early zone, or Mewtwo already fought', 'Check run context before waiting for another trigger.')]) + f'<p>The timing is a code schedule subject to these gates, not a promised spawn deadline. We have not completed this route.{ref(1)}</p>'),
        ('fight', 'Prepare for the arena rather than chasing the edge', f'<p>The special encounter confines the fight to a psychic arena. Its boundary pushes the player back; treating the outer edge as an unlimited escape route will not work as it would in an open zone. The fight adds attack types across phases and later recovery behavior, so leave room to react to the visible telegraphs.</p><p>Editorial preparation: bring damage you can apply while moving, keep a recovery/defensive layer, and avoid spending every slot on a hypothetical late combo. A static kit description cannot establish a universally strongest counter or clear-time record.{ref(1)}</p>'),
        ('capture', 'Classic victory still has a capture step', f'<p>In Classic, Mewtwo’s defeat is intercepted: the boss handler releases it into a special guaranteed capture takeover and displays the throw prompt. Approach and complete the interaction, then confirm the permanent League entry. Do not leave merely because the boss banner or free reward appeared.</p><p>That guarantee belongs to this special handoff. It does not mean every wild throw in the game is guaranteed. We inspected the handler, not a successful catch or save operation.{ref(1)}</p>'),
        ('survival', 'The 45-minute boss is not the same unlock route', f'<p>Survival milestone nine is nominally 9 × 300 = 2,700 seconds, or 45 minutes. Its special encounter is forced by the milestone scheduler; a previous boss can delay it. On defeat, the Survival branch does not call the Classic capture takeover.</p><p>Use Survival if your goal is endurance or the milestone itself. Use the eligible Classic route if your goal is permanently selecting Mewtwo from League. A screenshot of a Survival fight is not evidence of a permanent capture.{ref(1)}{ref(2)}</p>')],
        SOURCES, [('unlocks/', 'Check the prerequisite chain'), ('how-to-catch-pokemon/', 'Distinguish capture rewards'), ('how-to-win/', 'Complete a Classic map')])
    rarity = [(str(luck), *[f'{x:.2f}%' for x in rarity_weights(luck)]) for luck in [0, 50, 100]]
    article('luck-status-chance', 'PokeBonk Luck vs Status Chance: Which Upgrade Helps?', 'Choose Luck or Status Chance for the actual goal',
        'Compare Luck with Status Chance in PokeBonk using derived rarity-roll examples, per-hit status math and a checklist for Sleep or Burn challenges.',
        f'Choose Luck when the problem is reward/offering quality; choose Status Chance when you already have a status source and need more of its hits to apply that status. Status Damage is another stat: it strengthens damaging statuses rather than making a Sleep or Burn counter advance by itself.{ref(1)}', [
        ('choose', 'Pick the stat that can change your result', scope + table(['Goal', 'Relevant check', 'Why the other stat is not a substitute'], [('Better eligible rarity offers', 'Luck, your level/stage, and the actual offer pool.', 'Status Chance does not change the rarity roller.'), ('More Sleep/Burn applications', 'A source that applies that status, its base chance and Status Chance multiplier.', 'Luck alone does not add Sleep to a move.'), ('More burn/poison damage', 'Status Damage and the underlying hit/effect.', 'Higher damage is not automatically more distinct affected enemies.'), ('Survive the next crowded section', 'Your immediate recovery, mitigation and attack coverage.', 'A long-term offer advantage may not solve the current incoming damage.')]) + '<p>These are editorial choices based on the checked systems, not a claim that one stat has the best win rate.</p>'),
        ('rarity', 'Luck: compare normalized probabilities', f'<p>The original rarity roller uses several weights, normalizes them by their sum, and also reads level and stage. A larger Legendary weight is not the same percentage-point increase in final Legendary probability. The glossary’s rough “doubling” description is not a universal normalized probability formula.</p><p>The derived table holds player level at 20 and stage at 1, assumes nonnegative Luck, and uses the unrestricted ordinary rarity roll: no minimum-rarity or allowed-rarity mask. It describes that roll only, not an item drop rate, catch rate, guaranteed card or every reward source.</p>{ref(1)}' + table(['Luck', 'Common', 'Uncommon', 'Rare', 'Epic', 'Legendary'], rarity) + '<p>Method: a = Luck/100; effective score = level + Luck/8 + 12 × (stage−1). Weights are 70/(1+a), 24×(1+0.5a), 5×(1+a)²×ramp(3,10), 0.9×(1+a)³×ramp(8,18), and 0.12×(1+a)⁴×ramp(14,26). Each ramp clamps (score−low)/(high−low) to 0–1. Divide each weight by the sum. Rounded rows can differ from exactly 100% by 0.01.</p>'),
        ('status', 'Status Chance multiplies a source; it does not create one', f'<p>The move display uses a base status chance, move-upgrade factor and player Status Chance multiplier, capped at 100% for that hit. If a move has no status, that display does not gain one merely because the player multiplier rises.{ref(1)}</p>' + table(['Illustrative source', 'At ×1.0 Status Chance', 'At ×1.5', 'Interpretation'], [('A status move with 10% base chance and no status-specific upgrade', '10%', '15%', '+50% multiplier means 10% × 1.5, not 10% + 50 points.'), ('One Awakening stack in the inspected on-hit item handler', '2.5% Sleep', '3.75% Sleep', 'A source is present; still not a guaranteed Sleep on every hit.'), ('One Flame Orb stack in that handler', '5% Burn', '7.5% Burn', 'Fire damage and Burn application remain separate.'), ('A move with no applicable status source', 'No new status supplied by this stat', 'Still no source supplied', 'Add or inspect a real source before spending to amplify it.')]) + '<p>Examples isolate one handler and omit other conditional effects. They are arithmetic from the checked source, not measured application rates or a complete multi-source stacking model.</p>'),
        ('counter', 'When the challenge bar barely changes', f'<ol><li>Read whether the requirement is a cumulative total or a best single-run counter.</li><li>Check that a selected move/item actually applies the required status.</li><li>Compare the counter for distinct affected enemies, not total hits, damage or repeat applications to one enemy.</li><li>Keep mode, target and status source fixed while testing one change.</li></ol><p>The existing unlock reference gives actual Sleep/Burn targets and mode restrictions; do not replace those gates with an upgrade assumption.{ref(1)}{ref(2)}</p>')],
        SOURCES, [('items-vitamins/', 'Find actual stat sources'), ('unlocks/#status', 'Check Sleep and Burn targets'), ('builds/', 'Fit upgrades to the current kit')])
    article('abra-build', 'PokeBonk Abra Build: Psychic Moves & Fusion Decisions', 'Build Abra around its Psychic kit',
        'Plan Abra’s Psychic moves, Prismatic Premonition ingredients and defensive trade-offs. Compare three-slot and four-slot choices without a fake DPS ranking.',
        f'For Abra, start from its curated Psychic/Special kit and reserve space for Psybeam plus Future Sight if you want Prismatic Premonition. Magic Guard covers specific ground hazards and reduces projectile/area damage; it does not remove every survival problem. This is a source-based build plan, not a measured best-DPS build.{ref(1)}{ref(2)}', [
        ('kit', 'Use the League kit, not the raw Pokémon learnset', scope + table(['Kit choice', 'Planning role', 'Before spending'], [('Confusion', 'An available early Psychic/Special direction.', 'Improve a move that can hit your current problem while the pair is incomplete.'), ('Psybeam', 'One signature-fusion ingredient.', 'Keep a slot for the other ingredient; a marked plan does not force the offer.'), ('Psychic', 'A kit alternative when the signature pair is incomplete.', 'Taking another attack uses capacity and may delay the planned pair.'), ('Future Sight', 'The other signature-fusion ingredient.', 'Evaluate delayed impact against targets you can keep in range.')]) + f'<p>The League record supplies this four-move kit. A raw main-series Abra learnset focused on Teleport is not the playable run’s complete attack pool. Abra’s listed challenge is reaching level 30 in one run, then completing its capture; meeting that challenge does not itself select Abra for the next run.{ref(2)}</p>'),
        ('slots', 'Plan the slot conflict before the offers appear', table(['Available capacity', 'A coherent decision', 'Cost of a different choice'], [('Three move slots', 'Keep your useful opening attack plus Psybeam and Future Sight if both become available.', 'A fourth desired attack cannot fit before a slot is freed.'), ('Four move slots from the Lab', 'There is room for the signature pair plus two other useful attacks.', 'The capacity purchase does not unlock or guarantee either ingredient.'), ('Only one ingredient appears', 'Continue upgrading useful attacks and preserve survival; keep a fallback.', 'Repeatedly skipping useful choices can weaken the present run.'), ('Signature fusion completed', 'Two ingredients become one fusion, freeing capacity.', 'Read the new result’s scaling instead of assuming every old upgrade behaves identically.')]) + f'<p>At Bill’s Machine, the signature definition pairs Psybeam and Future Sight. Raise both to the required maximum, inspect the actual fusion option, then decide. No fixed offer order is claimed.{ref(1)}</p>'),
        ('stats', 'Check what each upgrade actually affects', f'<p>The listed kit and signature result use Special damage and Psychic type. Calcium’s Special target and a Psychic-specific effect describe different scopes; neither means every physical or off-type attack you add receives the same benefit.</p><p>The signature’s inspected part definition marks enemy-targeted rays; Area and additional-count behavior affect particular parts. Use the live fusion card after combining instead of importing a general “Projectiles improves everything” rule.</p><p>Magic Guard’s description covers damage from specified ground hazards and reduces projectile/area damage by 30%. The passive’s static modifier also lists a Special multiplier. It is not blanket immunity to contact, all boss attacks or poor positioning.{ref(1)}{ref(2)}</p>'),
        ('failure', 'Revise the plan from the failure you see', table(['Problem', 'Change to investigate', 'Keep constant for a useful comparison'], [('Dying to contact', 'Improve movement or a recovery/defensive layer; do not rely on ground-hazard immunity.', 'Map, difficulty and permanent upgrades.'), ('Targets leave delayed impacts', 'Review effective coverage/positioning and the attack you can use now.', 'Target type and currently owned moves.'), ('Pair never completes', 'Check unlocked/archived choices and whether slots are already full.', 'Same partner and eligible pool, not a different website edition.'), ('Strong-looking bonuses, low damage', 'Check Special/type/part scope rather than adding raw percentages together.', 'The actual move being compared.')]) + '<p>Record the offered choices and when the run failed. Until comparable runs exist, this plan cannot establish Abra’s rank, optimal fourth move or fastest clear.</p>')],
        SOURCES, [('builds/', 'Compare the three starter plans'), ('move-fusions/#finder', 'Check an actual pair'), ('lab/#costs', 'Budget move capacity')])
    new_slugs = ['how-to-win', 'how-to-catch-pokemon', 'mewtwo', 'luck-status-chance', 'abra-build']
    for slug in new_slugs:
        page = pages[P+slug+'/']
        page['html'] = re.sub(r'<figure>.*?</figure>', '', page['html'], flags=re.S)
        page['html'] = re.sub(r'<meta property="og:image"[^>]+>', '', page['html'])
        page['html'] = page['html'].replace('· Source-based guide</p>', '· By Megabonk.org · Source-based guide</p>')
    ctx['DATE'], ctx['VERSION'] = old

    def add(slug, ident, title, text):
        page = pages[P+slug+'/']
        page['html'] = page['html'].replace('<section class="sources"', f'<section id="{ident}"><h2>{title}</h2>{text}</section><section class="sources"', 1)
        toc_end = page['html'].find('</aside>')
        if toc_end >= 0:
            prefix, suffix = page['html'][:toc_end], page['html'][toc_end:]
            prefix = prefix.replace('<a href="#sources">Sources</a>', f'<a href="#{ident}">{title}</a><a href="#sources">Sources</a>')
            page['html'] = prefix + suffix

    add('beginners-guide', 'first-loop', 'Play the first run as a sequence', '<p>After choosing an available partner, select Classic, an unlocked map and a difficulty you can enter. For learning, we suggest Viridian Forest on Normal when available. Move into open space, collect experience and read the first level-up card: adding an attack, improving an existing move and taking a vitamin solve different problems.</p><p>Inspect the guardian objective and its nearby prompt. After winning that fight, collect the intended Great Ball reward and follow the portal. A finite Classic win requires the final encounter and exit; Survival instead continues through milestones. Return to the Lab with your actual accepted rewards and choose one upgrade that addresses the last failure.</p><p>For the complete objective chain and timer trap, use <a href="/pokebonk/how-to-win/">how to finish Classic</a>. This summary is a learning plan, not a recorded clear.</p>')
    add('beginners-guide', 'save-check', 'Before changing browser, account or host', '<p><strong>Different browser or website?</strong> Keep the old profile open and confirm the exact domain and trainer identity first. Our Play source and other third-party editions are separate from pokebonk.com; a familiar title does not establish shared progress.</p><p><strong>Want to keep a Guest?</strong> Inspect Save to account from the existing session. Confirm the game says it is preserving that Guest before leaving. We did not test conversion or recovery.</p><p><strong>Want deletion?</strong> Signing out or clearing browser data does not establish server deletion. The original project’s legal notice explains deletion requests through its contact route; use the contact in that original notice rather than sending a game password to this guide. The Guest retention policy is stated by the author, not tested here.<sup class="ref"><a href="#source-3" aria-label="Source 3">[3]</a></sup></p><p><strong>Want offline play?</strong> The original entry requires the web client and its account service. We have not verified a supported offline edition or accepted offline results. A local shortcut or cached screen does not prove either.</p>')
    add('beginners-guide', 'community', 'Find the project’s support, not a lookalike login', '<p>The original legal notice links the project Discord for community and support. For Reddit, local-language forums or repositories, verify who operates the destination; this guide has not established an official PokeBonk GitHub, Baha or Dcinside account. Use the original project’s current links to check that identity.</p><p><a href="/guides/pokemon-games-like-megabonk/">Looking for the Pokémon game from a video?</a> Distinguish PokeBonk from PokéSurvivor before following account, input or build instructions.</p>')
    add('builds', 'move-choice', 'Choose moves by the job they need to do', '<p><strong>Best moves depends on the task.</strong> For immediate survival, compare attacks you can use now, range/shape and whether you can keep hitting while moving. For a fusion goal, reserve both ingredients and their slots; a strong unrelated fourth choice may delay the pair. For a status challenge, check that a move applies the required status rather than selecting by type alone.</p><p>A fusion lookup answers “what does this pair make?”; it does not rank every ordinary move. The starter routes above are actual plans for their listed kits. <a href="/pokebonk/abra-build/">Abra needs a separate Psychic plan</a>, while <a href="/pokebonk/luck-status-chance/">Luck and Status Chance solve different upgrade problems</a>. No universal DPS or fastest-clear ordering is established.</p>')
    add('unlocks', 'capture-next', 'After the requirement table', '<p>A completed challenge makes an encounter eligible; it is not the entire capture procedure. <a href="/pokebonk/how-to-catch-pokemon/">Use the timed capture workflow</a> to distinguish League joins from Alpha support and Looks. <a href="/pokebonk/mewtwo/">Mewtwo uses a special Classic encounter</a>; Mew instead waits for the other 78 League members. Those are different targets.</p>')
    add('items-vitamins', 'stat-decision', 'Read the stat before selecting its source', '<p>The tables above list sources and static effects. For a worked decision, <a href="/pokebonk/luck-status-chance/">compare Luck’s normalized rarity roll with Status Chance’s per-hit multiplier</a>. More rarity is not the same as more Sleep applications, and more Status Damage is not itself another affected enemy.</p>')
    add('megabonk-vs-pokebonk', 'origin-check', 'Find a game by its actual project', '<p>If “Pokémon game like Megabonk” means the name of a 3D browser game, PokeBonk at pokebonk.com is one candidate. If it means choosing between Pokémon survivors, <a href="/guides/pokemon-games-like-megabonk/">compare PokeBonk and PokéSurvivor by the experience you want</a>. They are different projects and accounts.</p><p>Use the exact host linked by the author. A domain containing pokebonk, an app-style suffix, an installer icon or a familiar screenshot does not establish who operates it. This guide does not certify every third-party site as safe or unsafe. Keep an existing account’s host/profile before testing another edition.</p>')
    add('ko/beginners-guide', 'next-goal', '다음 목표에 맞춰 선택하기', '<p><strong>빌드:</strong> 스타터의 패시브와 현재 공격을 먼저 보세요. 불꽃 보너스와 물리·특수 보너스는 범위가 다릅니다. 융합 재료 두 개를 원하면 이동 슬롯을 먼저 남겨 두세요. 아이템을 많이 모았다는 사실만으로 가장 강한 조합이 되지는 않습니다.</p><p><strong>티어:</strong> 이 가이드는 통제된 승률 순위를 측정하지 않았습니다. 회복이 필요하면 이상해씨, 방어 여유가 필요하면 꼬부기처럼 현재 문제에 맞는 역할부터 비교하세요.</p><p><strong>친구와 플레이:</strong> 원작과 같은 계정·버전을 확인하고 협동 방의 생성/코드 참가 조건을 읽으세요. 클랜 가입만으로 같은 전투에 들어가는 것은 아닙니다. 상세 단계는 <a href="/pokebonk/multiplayer/">영어 협동 가이드</a>에 있습니다.</p>')
    for slug, link in [('maps', ('how-to-win/', 'Finish the final encounter and exit')), ('tier-list', ('abra-build/', 'Plan Abra’s Psychic kit'))]:
        pages[P+slug+'/']['html'] = pages[P+slug+'/']['html'].replace('<section class="related">', f'<p><a href="{P+link[0]}">{link[1]}</a></p><section class="related">', 1)
    cards = ''.join(f'<a href="{P+s}/">{t}<span>{d}</span></a>' for s,t,d in [
        ('how-to-win','Win a Classic run','Guardian → reward → final encounter → exit'),
        ('how-to-catch-pokemon','Complete the capture','League, support and shiny handoffs'),
        ('mewtwo','Find Mewtwo','Eligibility, encounter blockers and Survival distinction'),
        ('luck-status-chance','Luck or Status Chance?','Rarity math and per-hit examples'),
        ('abra-build','Abra build plan','Psychic kit, signature pair and slot conflicts')])
    for heading, slugs in [('Progression', ['how-to-catch-pokemon', 'mewtwo']),
                           ('Builds & choices', ['luck-status-chance', 'abra-build']),
                           ('World & rewards', ['how-to-win'])]:
        selected = ''.join(x+'</a>' for x in cards.split('</a>') if any(f'/{s}/' in x for s in slugs))
        marker = '<h3>'+heading+'</h3><div class="guide-index">'
        assert marker in pages[P]['html']
        pages[P]['html'] = pages[P]['html'].replace(marker, marker+selected, 1)
    for slug in ['beginners-guide', 'builds', 'unlocks', 'items-vitamins', 'megabonk-vs-pokebonk', 'ko/beginners-guide']:
        page = pages[P+slug+'/']
        n = len(re.findall(r'<li id="source-\d+"', page['html'])) + 1
        record = f'<li id="source-{n}">{ctx["ext"](CLIENT, "pokebonk.com — original v0.8.62 client")} — New task decisions checked October 28, 2026. Older reference sections retain their own dates. SINGLE_SOURCE, no completed-run or recovery test.</li>'
        page['html'] = page['html'].replace('</ol><a class="back"', record+'</ol><a class="back"', 1)
        page['html'] = page['html'].replace('<section class="sources"', f'<p>New task-specific additions reviewed October 28 against the original v0.8.62 client; recommendations remain source-based.{ref(n)}</p><section class="sources"', 1)
        page['html'] = page['html'].replace('이동 슬롯', '기술 슬롯')
